<script>
(function(){
'use strict';

/* ========== COIN RENDERER ========== */
var CoinRenderer = {
  /* Render a coin at time t (0-1) onto ctx, centered at (cx,cy) with given radius */
  render: function(ctx, cx, cy, radius, t, opts) {
    opts = opts || {};
    var edition = opts.edition || 'bronze';
    var colors = this.getColors(edition);
    var baseColor = colors.base;
    var lightColor = colors.light;
    var darkColor = colors.dark;
    var edgeColor = colors.edge;

    /* Animation angles from t */
    var yaw = t * Math.PI * 2;
    var pitch = Math.sin(yaw) * Math.PI / 3.2;
    var cosYaw = Math.cos(yaw);
    var cosPitch = Math.cos(pitch);
    var sinPitch = Math.sin(pitch);

    /* Apparent ellipse radii */
    var rx = radius * Math.max(0.12, Math.abs(cosPitch));
    var ry = radius * Math.max(0.12, Math.abs(cosPitch));

    /* Edge band width */
    var edgeW = radius * 0.08 * Math.max(0.15, Math.abs(cosPitch));

    /* Face visibility based on pitch */
    var faceVisible = cosPitch > 0.08;
    var backVisible = cosPitch < -0.08;
    var edgeVisible = Math.abs(cosPitch) < 0.85;

    ctx.save();

    /* Shadow */
    ctx.save();
    ctx.beginPath();
    ctx.ellipse(cx + 4, cy + 6, rx * 0.95, ry * 0.95, 0, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(0,0,0,0.35)';
    ctx.filter = 'blur(8px)';
    ctx.fill();
    ctx.restore();

    /* Edge band (side of cylinder) */
    if (edgeVisible || Math.abs(cosPitch) < 0.95) {
      this.drawEdge(ctx, cx, cy, rx, ry, edgeW, edgeColor, baseColor, yaw, cosPitch);
    }

    /* Face */
    if (faceVisible) {
      this.drawFace(ctx, cx, cy, rx * 0.88, ry * 0.88, baseColor, lightColor, darkColor, yaw, pitch, 'front');
    }
    if (backVisible) {
      this.drawFace(ctx, cx, cy, rx * 0.88, ry * 0.88, baseColor, lightColor, darkColor, yaw, pitch, 'back');
    }

    /* Specular highlight */
    this.drawHighlight(ctx, cx, cy, rx, ry, baseColor, lightColor, yaw, pitch, cosPitch);

    /* Reeded edge lines on top */
    if (edgeVisible || Math.abs(cosPitch) < 0.9) {
      this.drawReeding(ctx, cx, cy, rx + edgeW * 0.5, ry + edgeW * 0.5, edgeColor, cosPitch);
    }

    ctx.restore();
  },

  getColors: function(edition) {
    switch(edition) {
      case 'silver': return {base:'#b8b8c0', light:'#e8e8f0', dark:'#505060', edge:'#3a3a4a'};
      case 'gold':   return {base:'#d4a840', light:'#fff0a0', dark:'#8a6a20', edge:'#5a4a10'};
      case 'black':  return {base:'#3a3a42', light:'#6a6a74', dark:'#1a1a20', edge:'#0e0e14'};
      default:       return {base:'#b8884a', light:'#e8c880', dark:'#6a4a20', edge:'#4a3010'};
    }
  },

  drawEdge: function(ctx, cx, cy, rx, ry, ew, edgeColor, baseColor, yaw, cosPitch) {
    ctx.save();
    /* Draw the side of the cylinder as a filled shape */
    var topR = Math.max(1, rx);
    var botR = Math.max(1, rx);
    var topY = cy - ry;
    var botY = cy + ry;
    var sideH = ew * 2;

    /* Gradient for the edge */
    var eg = ctx.createLinearGradient(cx, topY - sideH, cx, topY + sideH);
    eg.addColorStop(0, edgeColor);
    eg.addColorStop(0.3, baseColor);
    eg.addColorStop(0.7, baseColor);
    eg.addColorStop(1, edgeColor);

    ctx.beginPath();
    ctx.ellipse(cx, cy, topR, topY + sideH - cy, 0, 0, Math.PI * 2);
    /* We draw the edge as a band */
    ctx.fillStyle = eg;
    ctx.fill();

    /* Inner shadow on face */
    var ig = ctx.createRadialGradient(cx, cy, rx * 0.7, cx, cy, rx * 1.05);
    ig.addColorStop(0, 'rgba(0,0,0,0)');
    ig.addColorStop(1, 'rgba(0,0,0,0.3)');
    ctx.beginPath();
    ctx.ellipse(cx, cy, rx, ry, 0, 0, Math.PI * 2);
    ctx.fillStyle = ig;
    ctx.fill();

    ctx.restore();
  },

  drawFace: function(ctx, cx, cy, rx, ry, baseColor, lightColor, darkColor, yaw, pitch, face) {
    ctx.save();
    /* Clip to ellipse */
    ctx.beginPath();
    ctx.ellipse(cx, cy, rx, ry, 0, 0, Math.PI * 2);
    ctx.clip();

    /* Base metallic gradient */
    var grad = ctx.createRadialGradient(cx - rx * 0.3, cy - ry * 0.3, 0, cx, cy, Math.max(rx, ry));
    grad.addColorStop(0, lightColor);
    grad.addColorStop(0.4, baseColor);
    grad.addColorStop(0.8, darkColor);
    grad.addColorStop(1, baseColor);
    ctx.fillStyle = grad;
    ctx.fillRect(cx - rx, cy - ry, rx * 2, ry * 2);

    /* Face-specific details */
    if (face === 'front') {
      this.drawFrontDesign(ctx, cx, cy, rx, ry, lightColor, darkColor, yaw);
    } else {
      this.drawBackDesign(ctx, cx, cy, rx, ry, lightColor, darkColor, yaw);
    }

    ctx.restore();
  },

  drawFrontDesign: function(ctx, cx, cy, r, ry, lightColor, darkColor, yaw) {
    /* Outer ring */
    ctx.beginPath();
    ctx.arc(cx, cy, r * 0.88, 0, Math.PI * 2);
    ctx.strokeStyle = darkColor;
    ctx.lineWidth = Math.max(1, r * 0.04);
    ctx.stroke();

    /* Inner ring */
    ctx.beginPath();
    ctx.arc(cx, cy, r * 0.72, 0, Math.PI * 2);
    ctx.strokeStyle = lightColor;
    ctx.lineWidth = Math.max(0.5, r * 0.015);
    ctx.stroke();

    /* Text around the ring - WASTEDTOKEN */
    ctx.save();
    ctx.font = 'bold ' + Math.max(6, r * 0.12) + 'px sans-serif';
    ctx.fillStyle = darkColor;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('WASTED', cx, cy - r * 0.38);
    ctx.fillText('TOKEN', cx, cy + r * 0.38);
    ctx.restore();

    /* Central emblem - a stylized shield/circle */
    ctx.save();
    ctx.beginPath();
    ctx.arc(cx, cy, r * 0.35, 0, Math.PI * 2);
    var cg = ctx.createRadialGradient(cx - r * 0.1, cy - r * 0.1, 0, cx, cy, r * 0.35);
    cg.addColorStop(0, lightColor);
    cg.addColorStop(0.6, darkColor);
    cg.addColorStop(1, baseColorFromLight(lightColor));
    ctx.fillStyle = cg;
    ctx.fill();
    ctx.strokeStyle = darkColor;
    ctx.lineWidth = Math.max(0.5, r * 0.02);
    ctx.stroke();

    /* WT monogram */
    ctx.font = 'bold ' + Math.max(5, r * 0.18) + 'px sans-serif';
    ctx.fillStyle = lightColor;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('WT', cx, cy);
    ctx.restore();

    /* Decorative dots around the emblem */
    for (var i = 0; i < 12; i++) {
      var a = (i / 12) * Math.PI * 2 + yaw * 0.3;
      var dx = cx + Math.cos(a) * r * 0.6;
      var dy = cy + Math.sin(a) * r * 0.6;
      ctx.beginPath();
      ctx.arc(dx, dy, Math.max(1, r * 0.015), 0, Math.PI * 2);
      ctx.fillStyle = lightColor;
      ctx.fill();
    }
  },

  drawBackDesign: function(ctx, cx, cy, r, ry, lightColor, darkColor, yaw) {
    /* Outer ring */
    ctx.beginPath();
    ctx.arc(cx, cy, r * 0.88, 0, Math.PI * 2);
    ctx.strokeStyle = lightColor;
    ctx.lineWidth = Math.max(1, r * 0.04);
    ctx.stroke();

    /* Inner circle */
    ctx.beginPath();
    ctx.arc(cx, cy, r * 0.78, 0, Math.PI * 2);
    ctx.strokeStyle = darkColor;
    ctx.lineWidth = Math.max(0.5, r * 0.015);
    ctx.stroke();

    /* Denomination */
    ctx.save();
    ctx.font = 'bold ' + Math.max(7, r * 0.16) + 'px sans-serif';
    ctx.fillStyle = lightColor;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('10,000', cx, cy - r * 0.12);
    ctx.font = 'bold ' + Math.max(5, r * 0.11) + 'px sans-serif';
    ctx.fillText('TOKENS', cx, cy + r * 0.18);
    ctx.restore();

    /* Bottom text */
    ctx.save();
    ctx.font = Math.max(4, r * 0.07) + 'px sans-serif';
    ctx.fillStyle = darkColor;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('WASTEDTOKEN MINT', cx, cy + r * 0.5);
    ctx.restore();
  },

  drawHighlight: function(ctx, cx, cy, rx, ry, baseColor, lightColor, yaw, pitch, cosPitch) {
    ctx.save();
    /* Specular highlight that moves across the surface */
    var hlAngle = yaw + Math.PI * 0.3;
    var hlX = cx + Math.cos(hlAngle) * rx * 0.35;
    var hlY = cy + Math.sin(hlAngle) * ry * 0.35 - Math.sin(pitch) * ry * 0.2;
    var hlR = Math.max(rx, ry) * 0.35;

    var hg = ctx.createRadialGradient(hlX, hlY, 0, hlX, hlY, hlR);
    hg.addColorStop(0, 'rgba(255,255,255,0.55)');
    hg.addColorStop(0.4, 'rgba(255,255,255,0.15)');
    hg.addColorStop(1, 'rgba(255,255,255,0)');

    ctx.beginPath();
    ctx.ellipse(cx, cy, rx, ry, 0, 0, Math.PI * 2);
    ctx.fillStyle = hg;
    ctx.fill();

    /* Secondary smaller highlight */
    var hl2X = cx - Math.cos(hlAngle) * rx * 0.2;
    var hl2Y = cy - Math.sin(hlAngle) * ry * 0.2 + Math.sin(pitch) * ry * 0.1;
    var hl2R = Math.max(rx, ry) * 0.15;
    var hg2 = ctx.createRadialGradient(hl2X, hl2Y, 0, hl2X, hl2Y, hl2R);
    hg2.addColorStop(0, 'rgba(255,255,255,0.3)');
    hg2.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.beginPath();
    ctx.ellipse(cx, cy, rx, ry, 0, 0, Math.PI * 2);
    ctx.fillStyle = hg2;
    ctx.fill();

    ctx.restore();
  },

  drawReeding: function(ctx, cx, cy, rx, ry, edgeColor, cosPitch) {
    ctx.save();
    ctx.beginPath();
    ctx.ellipse(cx, cy, rx, ry, 0, 0, Math.PI * 2);
    ctx.clip();

    var numLines = 48;
    var lineAlpha = Math.min(1, Math.abs(cosPitch) * 3);
    ctx.strokeStyle = edgeColor;
    ctx.lineWidth = 0.8;
    ctx.globalAlpha = lineAlpha * 0.6;

    for (var i = 0; i < numLines; i++) {
      var angle = (i / numLines) * Math.PI * 2;
      var x1 = cx + Math.cos(angle) * (rx + 1);
      var y1 = cy + Math.sin(angle) * (ry + 1);
      var x2 = cx + Math.cos(angle) * (rx + 3);
      var y2 = cy + Math.sin(angle) * (ry + 3);
      ctx.beginPath();
      ctx.moveTo(x1, y1);
      ctx.lineTo(x2, y2);
      ctx.stroke();
    }
    ctx.restore();
  }
};

function baseColorFromLight(lc) {
  /* Simple helper to get a darker version of light color */
  return '#6a6a70';
}

/* ========== EDITION RENDERER ========== */
function renderEditionCanvas(canvas, edition, t) {
  var ctx = canvas.getContext('2d');
  var w = canvas.width;
  var h = canvas.height;
  var cx = w / 2;
  var cy = h / 2;
  var radius = Math.min(w, h) * 0.38;
  CoinRenderer.render(ctx, cx, cy, radius, t, { edition: edition });
}

/* ========== ANIMATION CONTROLLER ========== */
var heroCanvas = document.getElementById('coin-hero');
var heroCtx = heroCanvas.getContext('2d');
var animTime = 0;
var isPaused = false;
var animFrameId = null;
var lastTimestamp = 0;
var speed = 0.15; /* seconds per full loop */

/* Set canvas size */
function resizeHeroCanvas() {
  var size = Math.min(420, window.innerWidth * 0.85);
  heroCanvas.width = size;
  heroCanvas.height = size;
  heroCanvas.style.width = size + 'px';
  heroCanvas.style.height = size + 'px';
}
resizeHeroCanvas();
window.addEventListener('resize', resizeHeroCanvas);

/* Render hero coin at time t (0-1) */
function renderHeroAtTime(t) {
  var w = heroCanvas.width;
  var h = heroCanvas.height;
  heroCtx.clearRect(0, 0, w, h);
  /* Simple backdrop */
  var bg = heroCtx.createRadialGradient(w/2, h/2, 0, w/2, h/2, w * 0.5);
  bg.addColorStop(0, '#16162a');
  bg.addColorStop(1, '#08080e');
  heroCtx.fillStyle = bg;
  heroCtx.fillRect(0, 0, w, h);
  /* Subtle glow behind coin */
  var glow = heroCtx.createRadialGradient(w/2, h/2, 0, w/2, h/2, w * 0.35);
  glow.addColorStop(0, 'rgba(180,160,100,0.08)');
  glow.addColorStop(1, 'rgba(0,0,0,0)');
  heroCtx.fillStyle = glow;
  heroCtx.fillRect(0, 0, w, h);
  /* Coin */
  CoinRenderer.render(heroCtx, w/2, h/2, w * 0.35, t, { edition: 'bronze' });
}

/* Animation loop */
function animate(timestamp) {
  if (isPaused) return;
  if (!lastTimestamp) lastTimestamp = timestamp;
  var dt = (timestamp - lastTimestamp) / 1000;
  lastTimestamp = timestamp;
  animTime += dt / speed;
  if (animTime >= 1) animTime -= 1;
  renderHeroAtTime(animTime);
  animFrameId = requestAnimationFrame(animate);
}

/* ========== DEMO API ========== */
window.demo = {
  canvas: heroCanvas,
  setTime: function(t) {
    /* Deterministic: same t always produces same pixels */
    renderHeroAtTime(((t % 1) + 1) % 1);
  },
  pause: function() {
    isPaused = true;
    if (animFrameId) {
      cancelAnimationFrame(animFrameId);
      animFrameId = null;
    }
  }
};

/* ========== INITIALIZATION ========== */
function init() {
  /* Render edition canvases */
  var editions = document.querySelectorAll('.edition');
  editions.forEach(function(el) {
    var canvas = el.querySelector('.edition-canvas');
    var edition = el.dataset.edition;
    if (canvas) {
      renderEditionCanvas(canvas, edition, 0.25);
    }
  });

  /* Start animation */
  animFrameId = requestAnimationFrame(animate);

  /* Buy button handlers */
  document.querySelectorAll('.buy').forEach(function(btn) {
    btn.addEventListener('click', function() {
      var edition = this.closest('.edition');
      var name = edition ? edition.dataset.edition : 'coin';
      this.textContent = 'Added!';
      this.style.background = '#5a8a5a';
      var self = this;
      setTimeout(function() {
        self.textContent = 'Add to cart';
        self.style.background = '';
      }, 1200);
    });
  });
}

/* Start when DOM is ready */
if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', init);
} else {
  init();
}

})();
</script>
